test('new operator pause and fatal player stop remain effective before and after the remaining claim',t=>{
  const f=timeoutFixture(t),latest=f.publishTimeout(),facade=reviewTimeoutRecoveryFacade(f.collector,latest);appendEvent(f.root,'pause',{reason:'operator-request'});assert.equal(facade.state().paused,true);
  const g=timeoutFixture(t),saved=g.publishTimeout(),running=reviewTimeoutRecoveryFacade(g.collector,saved);g.freshClaim();appendEvent(g.root,'pause',{reason:'operator-request'});assert.equal(running.state().paused,true);
  const h=timeoutFixture(t),authorized=h.publishTimeout(),active=reviewTimeoutRecoveryFacade(h.collector,authorized);appendEvent(h.root,'attempt-settled',{jobId:'future-player',fatal:true});assert.equal(active.state().paused,true);
  const i=timeoutFixture(t,{operatorPause:true});assert.throws(()=>validateReviewTimeoutRecovery(i.collector,i.timeoutRecovery,i.prior),/Operator or unrelated pause/);
});

test('remaining attempt requires the exact fresh guard marker and original transport source pins',t=>{
  const f=timeoutFixture(t),latest=f.publishTimeout(),second=f.freshClaim();assert.doesNotThrow(()=>verifyTimeoutTransport(f.collector,second.data.job,second.sequence,latest));const marker=join(f.root,'private/invocations/'+second.data.job.jobId+'/private/app-server/shutdown-guard.json');writeFileSync(marker,jsonBytes({schemaVersion:transportPolicyVersion,jobId:second.data.job.jobId,sourceHash:'a'.repeat(64)}));assert.throws(()=>verifyTimeoutTransport(f.collector,second.data.job,second.sequence,latest),/authorized shutdown guard/);rmSync(marker);assert.throws(()=>verifyTimeoutTransport(f.collector,second.data.job,second.sequence,latest));
  writeFileSync(join(f.root,'private/invocations/'+f.timeoutProof.jobId+'/private/app-server/shutdown-guard.json'),jsonBytes({schemaVersion:transportPolicyVersion,jobId:f.timeoutProof.jobId,sourceHash:shutdownSafeTransportSourceHash}));assert.throws(()=>verifyTimeoutTransport(f.collector,f.timeoutClaim.data.job,f.timeoutClaim.sequence,latest),/Historical call/);
});

test('changed predecessor, source, inventory, proof and shutdown delegation fail closed',t=>{
  const f=timeoutFixture(t);assert.doesNotThrow(()=>validateReviewTimeoutRecovery(f.collector,f.timeoutRecovery,f.prior));for(const mutate of [r=>r.previousPlayerContextRecoveryHash='a'.repeat(64),r=>r.transportDelegation.sourceHash='a'.repeat(64),r=>r.transportDelegation.processingAudit.reviewSourceDigest=f.player.recovery.processingBuild.sourceDigest,r=>r.playerContextDelegation.sourceHash='a'.repeat(64),r=>r.contextInventoryHash='a'.repeat(64),r=>r.proof.schemaVersion='trix-failed-review-invocation-1.0.0',r=>r.proof.acceptedResponse=true,r=>r.workerStartBinding.hash='a'.repeat(64)]){const changed=structuredClone(f.timeoutRecovery);mutate(changed);assert.throws(()=>validateReviewTimeoutRecovery(f.collector,changed,f.prior));}
});

test('runtime overrides only dispatch with approved frozen guard and preserves delegated policy audits',async t=>{
  const f=timeoutFixture(t),latest=f.publishTimeout(),facade=reviewTimeoutRecoveryFacade(f.collector,latest),verified=verifyReviewTimeoutRecoveryHistory(facade,{...f.timeoutHistoryOptions,latest}),second=f.freshClaim(),calls=[],baseRun=()=>{throw Error('No model calls in this fixture');},baseApi={verifyPriorHost(){calls.push('legacy-host');},exportRawGame(){calls.push('legacy-raw');}},importModule=async url=>url.endsWith('player-context-recovery.mjs')?{async buildPlayerContextRecoveryApis(){return {api:baseApi,runFullCampaign:baseRun,processingAudit:f.oldProcessingAudit,gameProcessingAudit:f.gameProcessingAudit};}}:{transportPolicyVersion,shutdownSafeTransportSourceHash,async dispatchShutdownSafeHostJob(_c,job){calls.push(job.jobId);return {bytes:Buffer.from('synthetic'),receipt:{synthetic:true}};}};
  const runtime=await buildReviewTimeoutRecoveryApis(facade,f.prior,verified,latest,{importModule});assert.equal(runtime.runFullCampaign,baseRun);assert.deepEqual(runtime.processingAudit,f.oldProcessingAudit);assert.deepEqual(runtime.gameProcessingAudit,f.gameProcessingAudit);assert.equal(runtime.api.exportRawGame,baseApi.exportRawGame);await runtime.api.dispatchHostJob(facade,second.data.job,{});assert.deepEqual(calls,[second.data.job.jobId]);runtime.api.verifyPriorHost(facade,second);assert.deepEqual(calls,[second.data.job.jobId,'legacy-host']);appendEvent(f.root,'pause',{reason:'operator-request'});await assert.rejects(()=>runtime.api.dispatchHostJob(facade,second.data.job,{}),/Later pause/);assert.equal(calls.length,2);
  await assert.rejects(()=>buildReviewTimeoutRecoveryApis(facade,f.prior,verified,{...latest,authorization:{...latest.authorization,hash:'a'.repeat(64)}},{importModule}),/Exact timeout authorization/);
});

